"""Generated by func2vec.generate_cluster.
Intent: k=5 dataset_size=small data_kind=tabular structure=hierarchical
Picked algorithm: sklearn.cluster.AgglomerativeClustering
Preprocessing (embedding-picked where applicable): ['sklearn.preprocessing.RobustScaler']
Evaluation (embedding-ranked): ['sklearn.metrics.davies_bouldin_score', 'sklearn.metrics.v_measure_score', 'sklearn.metrics.silhouette_score']
"""

import numpy as np
from sklearn.datasets import make_blobs
from sklearn.preprocessing import RobustScaler
from sklearn.cluster import AgglomerativeClustering
from sklearn.metrics import davies_bouldin_score
from sklearn.metrics import v_measure_score
from sklearn.metrics import silhouette_score


def load_data():
    X, y = make_blobs(n_samples=1500, centers=5, n_features=20,
                      cluster_std=1.2, random_state=42)
    return X, y


def build_pipeline():
    steps = []
    steps.append(RobustScaler())
    steps.append(AgglomerativeClustering(n_clusters=5, linkage='ward'))
    return steps


def run(X, y=None):
    steps = build_pipeline()
    Xt = X
    for step in steps[:-1]:
        Xt = step.fit_transform(Xt)
    clusterer = steps[-1]
    if hasattr(clusterer, 'fit_predict'):
        labels = clusterer.fit_predict(Xt)
    else:
        clusterer.fit(Xt)
        labels = clusterer.labels_

    scoreable = labels[labels != -1] if -1 in np.unique(labels) else labels
    Xs = Xt[labels != -1] if -1 in np.unique(labels) else Xt
    n_clusters = len(set(scoreable))
    print(f'algorithm    : {clusterer.__class__.__name__}')
    print(f'n_clusters   : {n_clusters}')
    if n_clusters >= 2:
        print(f'davies_bouldin_score    : {davies_bouldin_score(Xs, scoreable):.4f}')
        if y is not None:
            print(f'v_measure_score         : {v_measure_score(y, labels):.4f}')
        print(f'silhouette_score        : {silhouette_score(Xs, scoreable):.4f}')
    else:
        print('too few clusters formed to score')
    return labels


if __name__ == '__main__':
    X, y = load_data()
    run(X, y)
